(function(){'use strict';var C=window.CatchIt=window.CatchIt||{};var S=C.store;
var sliding=false;
var presets=[{id:'normal',icon:'🟢',title:'Штатный вечер',desc:'19:35 · 12 мин запаса, кофе',base:'19:35',bus:0,deltaS6:-300},{id:'hurry',icon:'🔴',title:'Красный режим: бежать!',desc:'19:42 · выигрыш на раннем поезде',base:'19:42',bus:0},{id:'option',icon:'🟣',title:'Бесплатный опцион',desc:'19:44 · шанс на раннюю электричку',base:'19:44',bus:0},{id:'day',icon:'☀️',title:'Дневное окно',desc:'10:45 · большой интервал',base:'10:45',bus:0},{id:'combo',icon:'⚡',title:'Комбо-режим CF',desc:'19:41 · ускорение на Окружной',base:'19:41',bus:0}];
var faults=[['apiTimeout','💥','Отвал API','Переход на локальный кэш'],['schemaErrorRecovered','🧩','Битая схема JSON','Восстановление и санитизация'],['targetTrainCancelled','🚫','Отмена электрички','Перестроить на следующий рейс'],['staleCache','⏳','Устаревший кэш','Расписанию больше 36 часов'],['mckHeadwayFallback','📡','Отвал сегмента МЦК','Ожидание по интервалу']];
function chip(label,action,value,active){return '<button class="chip '+(active?'selected':'')+'" data-action="'+action+'" data-value="'+value+'">'+label+'</button>';}
function panel(input,ui){var home=input.direction==='to_home';return '<div class="control-card"><div class="control-title"><div><span class="eyebrow muted">НАСТРОЙ ПОД СЕБЯ</span><h2>Параметры <span>✳</span></h2></div><span class="control-icon">☷</span></div>'+(home?'<div class="control-section"><div class="control-label"><div><span class="control-number">01</span><strong>Автобус 789</strong></div><button data-action="bus-slider" class="text-btn">'+(ui.showBusSlider?'СКРЫТЬ':'СЛАЙДЕР')+' ↗</button></div><p>Когда прибудет на остановку?</p><div class="chips">'+chip('🚌 В автобусе','bus','aboard',input.busMode==='aboard')+[1,3,5,10].map(function(n){return chip(n+' мин','bus',n,input.busMode==='manual'&&input.busWait===n);}).join('')+chip('Авто','bus','auto',input.busMode==='auto')+'</div>'+(ui.showBusSlider?'<label class="range-label">Ожидание: '+input.busWait+' мин<input type="range" min="0" max="20" step="1" value="'+input.busWait+'" data-input="busWait"></label>':'')+'</div><div class="control-section"><div class="control-label"><div><span class="control-number">02</span><strong>Время выхода</strong></div><button data-action="start-slider" class="text-btn">'+(ui.showStartSlider?'СКРЫТЬ':'СЛАЙДЕР')+' ↗</button></div><p>Когда планируешь отправиться?</p><div class="chips">'+[0,5,10,20].map(function(n){return chip(n===0?'Сейчас':'+'+n+' мин','start',n,input.startOffset===n);}).join('')+'</div>'+(ui.showStartSlider?'<label class="range-label">Сдвиг: +'+input.startOffset+' мин<input type="range" min="0" max="60" step="1" value="'+input.startOffset+'" data-input="startOffset"></label>':'')+'</div>':'<div class="control-section"><div class="control-label"><div><span class="control-number">01</span><strong>Время прибытия</strong></div></div><p>Когда нужно быть на Вешних Вод?</p><div class="chips">'+['09:00','10:30','12:00','14:00'].map(function(t){return chip('К '+t,'arrive',t,input.arriveBy===C.util.parse(t));}).join('')+'</div><label class="time-label">ТОЧНОЕ ВРЕМЯ <input type="time" data-input="arriveBy" value="'+C.util.time(input.arriveBy)+'"></label><label class="range-label">Время прибытия<input type="range" min="0" max="1439" step="5" value="'+Math.floor(input.arriveBy/60)+'" data-input="arriveSlider"></label></div>')+'<div class="control-info"><span>◉</span><p><strong>Расчёт по расписанию</strong><br>Данные демонстрационные, не являются расписанием перевозчика.</p></div><button class="qa-button" data-action="chaos"><span>⚗</span> QA / Chaos Simulator <b>↗</b></button></div>';}
function drawer(input,ui){if(!ui.isChaosDrawerOpen)return '';return '<div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="QA / Chaos Simulator"><div class="drawer-head"><div><span class="eyebrow">ПЕСОЧНИЦА / QA</span><h2>Chaos Simulator <span>⚗</span></h2><p>Проверяй маршрут в разных условиях.</p></div><button class="icon-btn" data-action="close-drawer" aria-label="Закрыть">×</button></div><div class="drawer-section"><div class="mini-title">A / ЖИЗНЕННЫЕ СЦЕНАРИИ <span>5 ПРЕСЕТОВ</span></div><div class="preset-list">'+presets.map(function(p){return '<button class="preset" data-action="preset" data-value="'+p.id+'"><span>'+p.icon+'</span><div><strong>'+p.title+'</strong><small>'+p.desc+'</small></div><b>↗</b></button>';}).join('')+'</div></div><div class="drawer-section"><div class="mini-title">B / FAULT INJECTION <span>5 СБОЕВ</span></div>'+faults.map(function(f){return '<div class="fault"><span>'+f[1]+'</span><div><strong>'+f[2]+'</strong><small>'+f[3]+'</small></div><button class="switch '+(input.faults[f[0]]?'on':'')+'" role="switch" aria-checked="'+input.faults[f[0]]+'" aria-label="'+f[2]+'" data-action="fault" data-value="'+f[0]+'"><span></span></button></div>';}).join('')+'</div><button class="reset-faults" data-action="reset-faults">Сбросить все сбои ↺</button></aside>';}
function render(dto,ui,input){document.querySelectorAll('[data-direction]').forEach(function(b){b.classList.toggle('active',b.dataset.direction===input.direction);b.setAttribute('aria-pressed',String(b.dataset.direction===input.direction));});document.querySelector('.intro-side strong').innerHTML=input.direction==='to_home'?'Вешних Вод <b>→</b> Катуар':'Катуар <b>→</b> Вешних Вод';if(!sliding){document.getElementById('controls').innerHTML=panel(input,ui);var mobile=document.getElementById('mobile-controls');var wasOpen=mobile.querySelector('details')&&mobile.querySelector('details').open;mobile.innerHTML='<details '+(wasOpen?'open':'')+'><summary><span><i>☷</i> Параметры поездки</span><b>НАСТРОИТЬ ↑</b></summary>'+panel(input,ui)+'</details>';}document.getElementById('drawer').innerHTML=drawer(input,ui);}
function handle(e){var el=e.target.closest('button');if(!el)return;if(el.dataset.direction){S.update({direction:el.dataset.direction});return;}if(el.dataset.layoutChoice){C.ThemeSwitcher.layout(el.dataset.layoutChoice);return;}if(el.id==='theme-button'){C.ThemeSwitcher.next();return;}var a=el.dataset.action,v=el.dataset.value;if(!a)return;
if(a==='chaos')S.updateUI({isChaosDrawerOpen:true});else if(a==='close-drawer')S.updateUI({isChaosDrawerOpen:false});else if(a==='force-calm')S.update({forceCalmToday:!S.input.forceCalmToday});else if(a==='expand')S.updateUI({expandedNodeId:S.ui.expandedNodeId===el.dataset.segment?null:el.dataset.segment});else if(a==='calibrate'){var key=el.dataset.segment==='S3'?'deltaS3':'deltaS6', patch={};patch[key]=+el.dataset.delta===0?0:Math.max(-300,Math.min(600,S.input[key]+ +el.dataset.delta));S.update(patch);}else if(a==='bus')S.update({busMode:v==='aboard'?'aboard':v==='auto'?'auto':'manual',busWait:isNaN(+v)?S.input.busWait:+v});else if(a==='start')S.update({startOffset:+v});else if(a==='arrive')S.update({arriveBy:C.util.parse(v)});else if(a==='bus-slider')S.updateUI({showBusSlider:!S.ui.showBusSlider});else if(a==='start-slider')S.updateUI({showStartSlider:!S.ui.showStartSlider});else if(a==='preset'){var p=presets.find(function(x){return x.id===v;});S.update({direction:'to_home',baseTime:C.util.parse(p.base),startOffset:0,busMode:'manual',busWait:p.bus,deltaS3:0,deltaS6:p.deltaS6||0,forceCalmToday:false,faults:{}});S.updateUI({isChaosDrawerOpen:false});}else if(a==='fault'){var f=Object.assign({},S.input.faults);f[v]=!f[v];S.update({faults:f});}else if(a==='reset-faults')S.update({faults:{}});
}
function input(e){var el=e.target, key=el.dataset.input;if(!key)return;if(key==='arriveBy'){if(el.value)S.update({arriveBy:C.util.parse(el.value)});}else if(key==='arriveSlider')S.update({arriveBy:+el.value*60});else if(key==='busWait')S.update({busWait:+el.value,busMode:'manual'});else if(key==='startOffset')S.update({startOffset:+el.value});}
C.Controls={render:render,init:function(){document.addEventListener('click',handle);document.addEventListener('input',function(e){if(e.target.type!=='range')return;sliding=true;input(e);sliding=false;var label=e.target.parentElement;if(e.target.dataset.input==='busWait')label.firstChild.nodeValue='Ожидание: '+e.target.value+' мин';if(e.target.dataset.input==='startOffset')label.firstChild.nodeValue='Сдвиг: +'+e.target.value+' мин';});document.addEventListener('change',input);document.addEventListener('keydown',function(e){if(e.key==='Escape'&&S.ui.isChaosDrawerOpen)S.updateUI({isChaosDrawerOpen:false});});document.addEventListener('click',function(e){if(e.target.classList.contains('drawer-backdrop'))S.updateUI({isChaosDrawerOpen:false});});}};
}());
